   AND SCHEDULE_ITEM_ID <> #{excludedScheduleItemId}

mapper.update:
UPDATE PLAN_SCHEDULE_ITEM
   SET TIME_SLOT = #{timeSlot},
       POSITION_NO = #{positionNo},
       ITEM_VERSION = ITEM_VERSION + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE SCHEDULE_ITEM_ID = #{scheduleItemId}
   AND PLAN_DAY_ID = #{planDayId}
   AND ITEM_VERSION = #{itemVersion}

UPDATE PLAN_SCHEDULE_ITEM
   SET PLAN_DAY_ID = #{targetPlanDayId},
       TIME_SLOT = #{timeSlot},
       POSITION_NO = #{positionNo},
       ITEM_VERSION = ITEM_VERSION + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE SCHEDULE_ITEM_ID = #{scheduleItemId}
   AND PLAN_DAY_ID = #{sourcePlanDayId}
   AND ITEM_VERSION = #{itemVersion}

