DELETE FROM PLAN_SCHEDULE_ITEM
 WHERE SCHEDULE_ITEM_ID = #{scheduleItemId}
   AND PLAN_DAY_ID = #{planDayId}
   AND ITEM_VERSION = #{itemVersion}

mapper.update:
UPDATE PLAN_SCHEDULE_ITEM
   SET POSITION_NO = POSITION_NO - 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_DAY_ID = #{planDayId}
   AND TIME_SLOT = #{timeSlot}
   AND POSITION_NO > #{removedPositionNo}

UPDATE PLAN_SCHEDULE_ITEM
   SET POSITION_NO = POSITION_NO + #{offset},
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_DAY_ID = #{planDayId}
   AND TIME_SLOT = #{timeSlot}

UPDATE PLAN_SCHEDULE_ITEM
   SET POSITION_NO = #{positionNo},
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE SCHEDULE_ITEM_ID = #{scheduleItemId}
   AND PLAN_DAY_ID = #{planDayId}
   AND TIME_SLOT = #{timeSlot}

